  uint256 owing = dividendsOwing(account);
  if(owing > 0) {
    unclaimedDividends = unclaimedDividends.sub(owing);

    account.transfer(owing);
  }
  accounts[account].lastDividendPoints = totalDividendPoints;
  _;
